static JSValue
ns_window_btoa(JSContext *ctx, JSValueConst this_val,
               int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 1) return JS_NewString(ctx, "");
    size_t slen = 0;
    const char *s = JS_ToCStringLen(ctx, &slen, argv[0]);
    if (!s) return JS_NewString(ctx, "");
    GByteArray *bytes = g_byte_array_sized_new(slen);
    const char *p = s, *end = s + slen;
    while (p < end) {
        gunichar cp = g_utf8_get_char_validated(p, end - p);
        guint8 b;
        if (*p == '\0') {
            b = 0;
            p++;
        } else if (cp == (gunichar)-1 || cp == (gunichar)-2) {
            g_byte_array_free(bytes, TRUE);
            JS_FreeCString(ctx, s);
            return ns_throw_dom_exception(ctx, "InvalidCharacterError", 5,
                "String contains an invalid character");
        } else if (cp > 0xFF) {
            g_byte_array_free(bytes, TRUE);
            JS_FreeCString(ctx, s);
            return ns_throw_dom_exception(ctx, "InvalidCharacterError", 5,
                "String contains an invalid character");
        } else {
            b = (guint8)cp;
            p = g_utf8_next_char(p);
        }
        g_byte_array_append(bytes, &b, 1);
    }
    JS_FreeCString(ctx, s);
    gchar *b64 = g_base64_encode(bytes->data, bytes->len);
    g_byte_array_free(bytes, TRUE);
    JSValue r = JS_NewString(ctx, b64);
    g_free(b64);
    return r;
}

static JSValue
ns_window_atob(JSContext *ctx, JSValueConst this_val,
               int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 1) return JS_NewString(ctx, "");
    size_t slen = 0;
    const char *s = JS_ToCStringLen(ctx, &slen, argv[0]);
    if (!s) return JS_NewString(ctx, "");
    GString *clean = g_string_sized_new(slen + 4);
    for (size_t i = 0; i < slen; i++) {
        unsigned char c = (unsigned char)s[i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f') continue;
        g_string_append_c(clean, (char)c);
    }
    if (clean->len % 4 == 0) {
        if (clean->len >= 2 &&
            clean->str[clean->len - 1] == '=' &&
            clean->str[clean->len - 2] == '=')
            g_string_truncate(clean, clean->len - 2);
        else if (clean->len >= 1 && clean->str[clean->len - 1] == '=')
            g_string_truncate(clean, clean->len - 1);
    }
    if (clean->len % 4 == 1) {
        g_string_free(clean, TRUE);
        JS_FreeCString(ctx, s);
        return ns_throw_dom_exception(ctx, "InvalidCharacterError", 5,
            "The string to be decoded is not correctly encoded");
    }
    for (gsize i = 0; i < clean->len; i++) {
        unsigned char c = (unsigned char)clean->str[i];
        gboolean ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                      (c >= '0' && c <= '9') || c == '+' || c == '/';
        if (!ok) {
            g_string_free(clean, TRUE);
            JS_FreeCString(ctx, s);
            return ns_throw_dom_exception(ctx, "InvalidCharacterError", 5,
                "The string to be decoded is not correctly encoded");
        }
    }
    while (clean->len % 4 != 0)
        g_string_append_c(clean, '=');
    gsize out_len = 0;
    guchar *out = g_base64_decode(clean->str, &out_len);
    g_string_free(clean, TRUE);
    JS_FreeCString(ctx, s);
    if (!out) return JS_NewStringLen(ctx, "", 0);
    GByteArray *utf8 = g_byte_array_sized_new(out_len + out_len / 2 + 1);
    for (gsize i = 0; i < out_len; i++) {
        guint8 b = out[i];
        if (b < 0x80) {
            g_byte_array_append(utf8, &b, 1);
        } else {
            guint8 two[2] = { (guint8)(0xC0 | (b >> 6)),
                              (guint8)(0x80 | (b & 0x3F)) };
            g_byte_array_append(utf8, two, 2);
        }
    }
    g_free(out);
    JSValue r = JS_NewStringLen(ctx, (const char *)utf8->data, utf8->len);
    g_byte_array_free(utf8, TRUE);
    return r;
}

static JSValue
ns_url_get_searchParams_object(JSContext *ctx, const char *search);

static JSValue
ns_url_get_searchParams_value(JSContext *ctx, JSValueConst init,
                              JSValueConst proto);

static JSValue
ns_url_construct(JSContext *ctx, JSValueConst new_target,
                 int argc, JSValueConst *argv);

static JSValue
ns_url_parts_to_js(JSContext *ctx, const char *href)
{
    g_autoptr(ns_url_parts) parts = ns_url_parts_new(href);
    if (!parts) return JS_NULL;
    JSValue o = JS_NewObject(ctx);
    JS_SetPropertyStr(ctx, o, "href",     JS_NewString(ctx, parts->href));
    JS_SetPropertyStr(ctx, o, "protocol", JS_NewString(ctx, parts->protocol));
    JS_SetPropertyStr(ctx, o, "host",     JS_NewString(ctx, parts->host));
    JS_SetPropertyStr(ctx, o, "hostname", JS_NewString(ctx, parts->hostname));
    JS_SetPropertyStr(ctx, o, "port",     JS_NewString(ctx, parts->port));
    JS_SetPropertyStr(ctx, o, "origin",   JS_NewString(ctx, parts->origin));
    JS_SetPropertyStr(ctx, o, "pathname", JS_NewString(ctx, parts->pathname));
    JS_SetPropertyStr(ctx, o, "search",   JS_NewString(ctx, parts->search));
    JS_SetPropertyStr(ctx, o, "hash",     JS_NewString(ctx, parts->hash));
    JS_SetPropertyStr(ctx, o, "username", JS_NewString(ctx, parts->username));
    JS_SetPropertyStr(ctx, o, "password", JS_NewString(ctx, parts->password));
    return o;
}

static JSValue
ns_window_url_parts_internal(JSContext *ctx, JSValueConst this_val,
                             int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 1) return JS_NULL;
    const char *href = JS_ToCString(ctx, argv[0]);
    if (!href) return JS_NULL;
    JSValue o = ns_url_parts_to_js(ctx, href);
    JS_FreeCString(ctx, href);
    return o;
}

static JSValue
ns_window_url_set_internal(JSContext *ctx, JSValueConst this_val,
                           int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 3) return JS_NULL;
    const char *href = JS_ToCString(ctx, argv[0]);
    const char *comp = JS_ToCString(ctx, argv[1]);
    size_t val_len = 0;
    const char *val  = JS_ToCStringLen(ctx, &val_len, argv[2]);
    JSValue o = JS_NULL;
    if (href && comp && val) {
        char *next = ns_url_set_component_len(href, comp, val, val_len);
        if (next) {
            o = ns_url_parts_to_js(ctx, next);
            g_free(next);
        }
    }
    if (href) JS_FreeCString(ctx, href);
    if (comp) JS_FreeCString(ctx, comp);
    if (val)  JS_FreeCString(ctx, val);
    return o;
}

static JSValue
ns_window_url_can_parse(JSContext *ctx, JSValueConst this_val,
                        int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 1)
        return JS_ThrowTypeError(ctx, "URL.canParse: 1 argument required");
    JSValue tmp = ns_url_construct(ctx, JS_UNDEFINED, argc, argv);
    if (JS_IsException(tmp)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        return JS_FALSE;
    }
    JS_FreeValue(ctx, tmp);
    return JS_TRUE;
}

static JSValue
ns_window_url_parse_static(JSContext *ctx, JSValueConst this_val,
                           int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 1)
        return JS_ThrowTypeError(ctx, "URL.parse: 1 argument required");
    JSValue tmp = ns_url_construct(ctx, JS_UNDEFINED, argc, argv);
    if (JS_IsException(tmp)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        return JS_NULL;
    }
    return tmp;
}

static void
ns_url_install_interface(JSContext *ctx)
{
    static const char *src =
        "(function(){"
        " try { new URL('http://e/'); } catch(e) {}"
        " try { Object.defineProperty(globalThis, 'URL', { enumerable: false }); } catch(e) {}"
        " try { Object.defineProperty(URL, 'prototype', { writable: false }); } catch(e) {}"
        "})()";
    JSValue r = JS_Eval(ctx, src, strlen(src), "<url-iface>", JS_EVAL_TYPE_GLOBAL | JS_EVAL_FLAG_HIDE_SOURCE);
    if (JS_IsException(r)) JS_FreeValue(ctx, JS_GetException(ctx));
    JS_FreeValue(ctx, r);
}

static void
ns_usp_install_interface(JSContext *ctx)
{
    static const char *src =
        "(function(){"
        " try { new URLSearchParams(''); } catch(e) {}"
        " try { Object.defineProperty(globalThis, 'URLSearchParams', { enumerable: false }); } catch(e) {}"
        " try { Object.defineProperty(URLSearchParams, 'prototype', { writable: false }); } catch(e) {}"
        "})()";
    JSValue r = JS_Eval(ctx, src, strlen(src), "<usp-iface>", JS_EVAL_TYPE_GLOBAL | JS_EVAL_FLAG_HIDE_SOURCE);
    if (JS_IsException(r)) JS_FreeValue(ctx, JS_GetException(ctx));
    JS_FreeValue(ctx, r);
}

static char *
ns_url_resolve_args(JSContext *ctx, int argc, JSValueConst *argv,
                    const char *raw, size_t raw_len)
{
    char *resolved = NULL;
    if (argc >= 2 && !JS_IsUndefined(argv[1]) && !JS_IsNull(argv[1])) {
        const char *base = JS_ToCString(ctx, argv[1]);
        if (base) {
            resolved = ns_url_resolve_len(base, raw, raw_len);
            JS_FreeCString(ctx, base);
        }
        if (!resolved)
            JS_ThrowTypeError(ctx, "URL: invalid url");
        return resolved;
    }
    resolved = ns_url_resolve_len(NULL, raw, raw_len);
    if (!resolved)
        JS_ThrowTypeError(ctx, "URL: invalid or relative URL requires a base");
    return resolved;
}

static JSValue
ns_url_data_object(JSContext *ctx, const char *resolved)
{
    ns_url_parts *parts = ns_url_parts_new(resolved);
    JSValue obj = JS_NewObject(ctx);
    if (parts) {
        JS_SetPropertyStr(ctx, obj, "href",     JS_NewString(ctx, parts->href));
        JS_SetPropertyStr(ctx, obj, "protocol", JS_NewString(ctx, parts->protocol));
        JS_SetPropertyStr(ctx, obj, "host",     JS_NewString(ctx, parts->host));
        JS_SetPropertyStr(ctx, obj, "hostname", JS_NewString(ctx, parts->hostname));
        JS_SetPropertyStr(ctx, obj, "port",     JS_NewString(ctx, parts->port));
        JS_SetPropertyStr(ctx, obj, "origin",   JS_NewString(ctx, parts->origin));
        JS_SetPropertyStr(ctx, obj, "pathname",
                          JS_NewString(ctx, parts->pathname));
        JS_SetPropertyStr(ctx, obj, "search",   JS_NewString(ctx, parts->search));
        JS_SetPropertyStr(ctx, obj, "hash",     JS_NewString(ctx, parts->hash));
        JS_SetPropertyStr(ctx, obj, "username", JS_NewString(ctx, parts->username));
        JS_SetPropertyStr(ctx, obj, "password", JS_NewString(ctx, parts->password));
        const char *q = *parts->search ? parts->search + 1 : "";
        JS_SetPropertyStr(ctx, obj, "searchParams",
                          ns_url_get_searchParams_object(ctx, q));
        ns_url_parts_free(parts);
    } else {
        JS_SetPropertyStr(ctx, obj, "href",     JS_NewString(ctx, resolved));
        JS_SetPropertyStr(ctx, obj, "protocol", JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "host",     JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "hostname", JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "port",     JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "origin",   JS_NewString(ctx, "null"));
        JS_SetPropertyStr(ctx, obj, "pathname", JS_NewString(ctx, "/"));
        JS_SetPropertyStr(ctx, obj, "search",   JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "hash",     JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "username", JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "password", JS_NewString(ctx, ""));
        JS_SetPropertyStr(ctx, obj, "searchParams",
                          ns_url_get_searchParams_object(ctx, ""));
    }
    return obj;
}

static void
ns_url_install_helper(JSContext *ctx, ns_js *jsx)
{
    static const char *helper_src =
        "(function(urlParts, urlSet){ "
        " return function(u, proto){ "
        "  var URLp = URL.prototype; "
        "  if (!URLp.__ndReady) { "
        "    function nm(fn, n){ try { Object.defineProperty(fn, 'name', { value: n, configurable: true }); } catch(e) {} return fn; } "
        "    function st(o){ var d = o !== null && typeof o === 'object' ? o.__nd : undefined; if (!d) throw new TypeError('Illegal invocation'); return d; } "
        "    function gettr(name){ return function(){ return st(this)[name]; }; } "
        "    function setComp(comp){ return function(v){ var d = st(this); var p = urlSet(d.href, comp, String(v)); if (p) { this.__nd = p; this.__ndSync(); } }; } "
        "    function accessor(name, setter){ Object.defineProperty(URLp, name, { configurable: true, enumerable: true, get: nm(gettr(name), 'get ' + name), set: setter ? nm(setter, 'set ' + name) : undefined }); } "
        "    accessor('href', function(v){ st(this); var p = urlParts(String(v)); if (!p) throw new TypeError('Invalid URL'); this.__nd = p; this.__ndSync(); }); "
        "    accessor('origin', undefined); "
        "    ['protocol','username','password','host','hostname','port','pathname','search','hash'].forEach(function(n){ accessor(n, setComp(n)); }); "
        "    Object.defineProperty(URLp, 'searchParams', { configurable: true, enumerable: true, get: nm(function(){ st(this); return this.__ndSP; }, 'get searchParams') }); "
        "    function method(name, fn){ Object.defineProperty(URLp, name, { configurable: true, enumerable: true, writable: true, value: nm(fn, name) }); } "
        "    method('toString', function(){ return st(this).href; }); "
        "    method('toJSON', function(){ return st(this).href; }); "
        "    URLp.__ndSync = function(){ try { var sp = new URLSearchParams(this.__nd.search); if (this.__ndSP) { this.__ndSP.__ndPairs = sp.__ndPairs; } else { sp.__ndOwner = this; this.__ndSP = sp; } } catch(e) {} }; "
        "    URLp.__ndSetSearchRaw = function(v){ var p = urlSet(this.__nd.href, 'search', String(v)); if (p) { this.__nd = p; this.__ndSync(); } }; "
        "    try { Object.defineProperty(URLp, Symbol.toStringTag, { value: 'URL', configurable: true }); } catch(e) {} "
        "    URLp.__ndReady = true; "
        "  } "
        "  var nd = { href: u.href, origin: u.origin, protocol: u.protocol, username: u.username, password: u.password, host: u.host, hostname: u.hostname, port: u.port, pathname: (u.pathname == null ? '' : u.pathname), search: u.search || '', hash: u.hash || '' }; "
        "  var inst = Object.create(proto && (proto === URLp || URLp.isPrototypeOf(proto)) ? proto : URLp); "
        "  inst.__nd = nd; "
        "  inst.__ndSync(); "
        "  return inst; "
        " }; "
        "}) ";
    JSValue factory = JS_Eval(ctx, helper_src, strlen(helper_src),
                              "<url-helper>", JS_EVAL_TYPE_GLOBAL | JS_EVAL_FLAG_HIDE_SOURCE);
    JSValue h = JS_UNDEFINED;
    if (!JS_IsException(factory)) {
        JSValue parts_fn = JS_NewCFunction(ctx, ns_window_url_parts_internal,
                                           "parts", 1);
        JSValue set_fn = JS_NewCFunction(ctx, ns_window_url_set_internal,
                                         "set", 3);
        JSValueConst fargs[2] = { parts_fn, set_fn };
        h = JS_Call(ctx, factory, JS_UNDEFINED, 2, fargs);
        JS_FreeValue(ctx, parts_fn);
        JS_FreeValue(ctx, set_fn);
    }
    JS_FreeValue(ctx, factory);
    int *url_set = NULL;
    JSValue *url_helper = ns_js_helper(jsx, ctx, NS_HELPER_URL, &url_set);
    if (!JS_IsException(h)) {
        *url_helper = h;
        *url_set = 1;
    } else {
        JS_FreeValue(ctx, JS_GetException(ctx));
        JS_FreeValue(ctx, h);
    }
}

static JSValue
ns_url_wrap_instance(JSContext *ctx, ns_js *jsx, JSValue obj, JSValueConst new_target)
{
    JSValue new_proto = JS_IsObject(new_target)
        ? JS_GetPropertyStr(ctx, new_target, "prototype") : JS_UNDEFINED;
    JSValueConst args[2] = { obj, new_proto };
    int *url_set = NULL;
    JSValue *url_helper = ns_js_helper(jsx, ctx, NS_HELPER_URL, &url_set);
    JSValue r = JS_Call(ctx, *url_helper, JS_UNDEFINED, 2, args);
    JS_FreeValue(ctx, new_proto);
    if (JS_IsException(r)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        JS_FreeValue(ctx, r);
        return obj;
    }
    JS_FreeValue(ctx, obj);
    return r;
}

static JSValue
ns_url_construct(JSContext *ctx, JSValueConst new_target,
                 int argc, JSValueConst *argv)
{
    if (argc < 1) return JS_ThrowTypeError(ctx, "URL: requires a url string");
    size_t raw_len = 0;
    const char *raw = JS_ToCStringLen(ctx, &raw_len, argv[0]);
    if (!raw) return JS_ThrowTypeError(ctx, "URL: invalid url argument");
    char *resolved = ns_url_resolve_args(ctx, argc, argv, raw, raw_len);
    JS_FreeCString(ctx, raw);
    if (!resolved) return JS_EXCEPTION;
    JSValue obj = ns_url_data_object(ctx, resolved);
    g_free(resolved);
    ns_js *jsx = js_from_ctx(ctx);
    int *url_set = NULL;
    if (jsx) ns_js_helper(jsx, ctx, NS_HELPER_URL, &url_set);
    if (url_set && !*url_set) ns_url_install_helper(ctx, jsx);
    if (url_set && *url_set)
        return ns_url_wrap_instance(ctx, jsx, obj, new_target);
    return obj;
}

static JSValue
ns_window_url_ctor(JSContext *ctx, JSValueConst this_val,
                   int argc, JSValueConst *argv)
{
    if (!JS_IsObject(this_val))
        return JS_ThrowTypeError(ctx, "Failed to construct 'URL': Please use "
            "the 'new' operator, this DOM object constructor cannot be "
            "called as a function.");
    return ns_url_construct(ctx, this_val, argc, argv);
}

static JSValue
ns_url_get_searchParams_value(JSContext *ctx, JSValueConst init,
                              JSValueConst proto)
{
    ns_js *jsx = js_from_ctx(ctx);
    int *usp_helper_set = NULL;
    JSValue *usp_helper = jsx ? ns_js_helper(jsx, ctx, NS_HELPER_SEARCH_PARAMS, &usp_helper_set) : NULL;
    if (usp_helper && !*usp_helper_set) {
        static const char *helper_src =
            "(function(init, proto){ "
            " var USPp = URLSearchParams.prototype; "
            " if (!USPp.__ndReady) { "
            "   function nm(fn,n){ try { Object.defineProperty(fn,'name',{ value:n, configurable:true }); } catch(e){} return fn; } "
            "   function fenc(s){ return encodeURIComponent(String(s)).replace(/[!~'()]/g,function(c){return '%'+c.charCodeAt(0).toString(16).toUpperCase();}).replace(/%20/g,'+'); } "
            "   function chk(o){ var p = o !== null && typeof o === 'object' ? o.__ndPairs : undefined; if (!Array.isArray(p)) throw new TypeError('Illegal invocation'); return p; } "
            "   function meth(name, fn){ Object.defineProperty(USPp, name, { configurable:true, enumerable:true, writable:true, value:nm(fn,name) }); } "
            "   function req(n,c){ if (c < n) throw new TypeError(n+' arguments required'); } "
            "   USPp.__ndNotify = function(){ var ow = this.__ndOwner; if (ow && ow.__ndSetSearchRaw) { var s = this.toString(); ow.__ndSetSearchRaw(s ? '?' + s : ''); } }; "
            "   meth('toString', function(){ return chk(this).map(function(p){return fenc(p[0])+'='+fenc(p[1]);}).join('&'); }); "
            "   meth('get', function(k){ var P = chk(this); req(1,arguments.length); k=String(k); for (var i=0;i<P.length;i++) if(P[i][0]===k) return P[i][1]; return null; }); "
            "   meth('getAll', function(k){ var P = chk(this); req(1,arguments.length); k=String(k); var r=[]; for (var i=0;i<P.length;i++) if(P[i][0]===k) r.push(P[i][1]); return r; }); "
            "   meth('has', function(k){ var P = chk(this); req(1,arguments.length); k=String(k); var hv=arguments.length>1&&arguments[1]!==undefined; var vv=hv?String(arguments[1]):null; for (var i=0;i<P.length;i++) if(P[i][0]===k&&(!hv||P[i][1]===vv)) return true; return false; }); "
            "   meth('set', function(k,v){ var P = chk(this); req(2,arguments.length); k=String(k); v=String(v); var found=false; var out=[]; for (var i=0;i<P.length;i++){ if(P[i][0]===k){ if(!found){out.push([k,v]);found=true;} } else out.push(P[i]); } if(!found) out.push([k,v]); this.__ndPairs=out; this.__ndNotify(); }); "
            "   meth('append', function(k,v){ var P = chk(this); req(2,arguments.length); P.push([String(k),String(v)]); this.__ndNotify(); }); "
            "   meth('delete', function(k){ var P = chk(this); req(1,arguments.length); k=String(k); var hv=arguments.length>1&&arguments[1]!==undefined; var vv=hv?String(arguments[1]):null; this.__ndPairs=P.filter(function(p){return !(p[0]===k&&(!hv||p[1]===vv));}); this.__ndNotify(); }); "
            "   meth('sort', function(){ var P = chk(this); P.sort(function(a,b){return a[0]<b[0]?-1:a[0]>b[0]?1:0;}); this.__ndNotify(); }); "
            "   meth('forEach', function(cb){ var P = chk(this); req(1,arguments.length); if (typeof cb !== 'function') throw new TypeError(\"Failed to execute 'forEach' on 'URLSearchParams': parameter 1 is not of type 'Function'.\"); var th=arguments[1]; for (var i=0;i<this.__ndPairs.length;i++){ var e=this.__ndPairs[i]; cb.call(th,e[1],e[0],this); } }); "
            "   function* walk(o, kind){ for (var i=0;i<o.__ndPairs.length;i++){ var e=o.__ndPairs[i]; yield kind===0?[e[0],e[1]]:kind===1?e[0]:e[1]; } } "
            "   meth('keys', function(){ chk(this); return walk(this, 1); }); "
            "   meth('values', function(){ chk(this); return walk(this, 2); }); "
            "   meth('entries', function(){ chk(this); return walk(this, 0); }); "
            "   Object.defineProperty(USPp, Symbol.iterator, { configurable:true, writable:true, value:USPp.entries }); "
            "   Object.defineProperty(USPp,'size',{ configurable:true, enumerable:true, get:nm(function(){ return chk(this).length; },'get size') }); "
            "   try { Object.defineProperty(USPp,Symbol.toStringTag,{ value:'URLSearchParams', configurable:true }); } catch(e){} "
            "   USPp.__ndReady = true; "
            " } "
            " var pairs=[]; "
            " function usv(s){s=String(s);var o='',i;for(i=0;i<s.length;i++){var c=s.charCodeAt(i);if(c>=0xD800&&c<=0xDBFF){var d=i+1<s.length?s.charCodeAt(i+1):0;if(d>=0xDC00&&d<=0xDFFF){o+=s[i]+s[i+1];i++;}else o+='�';}else if(c>=0xDC00&&c<=0xDFFF){o+='�';}else{o+=s[i];}}return o;} "
            " function add(k,v){pairs.push([usv(k),usv(v)]);} "
            " function pdecode(s){ "
            "   s=String(s).replace(/\\+/g,' '); "
            "   var out=[]; "
            "   for (var i=0;i<s.length;){ "
            "     if (s.charCodeAt(i)===37 && i+2<s.length && /^[0-9a-fA-F]{2}$/.test(s.substr(i+1,2))){ "
            "       out.push(parseInt(s.substr(i+1,2),16)); i+=3; continue; "
            "     } "
            "     var cp=s.codePointAt(i); i+=cp>65535?2:1; "
            "     if (cp<128) out.push(cp); "
            "     else if (cp<2048) out.push(192|(cp>>6),128|(cp&63)); "
            "     else if (cp<65536) out.push(224|(cp>>12),128|((cp>>6)&63),128|(cp&63)); "
            "     else out.push(240|(cp>>18),128|((cp>>12)&63),128|((cp>>6)&63),128|(cp&63)); "
            "   } "
            "   return new TextDecoder('utf-8').decode(new Uint8Array(out)); "
            " } "
            " function parse(q){ "
            "   if (q && q[0]==='?') q=q.slice(1); "
            "   if (!q) return; "
            "   var parts=String(q).split('&'); "
            "   for (var i=0;i<parts.length;i++){ "
            "     if (!parts[i]) continue; "
            "     var eq=parts[i].indexOf('='); "
            "     var k=eq<0?parts[i]:parts[i].slice(0,eq); "
            "     var v=eq<0?'':parts[i].slice(eq+1); "
            "     add(pdecode(k),pdecode(v)); "
            "   } "
            " } "
            " if (init == null) { "
            " } else if (typeof init === 'string') { "
            "   parse(init); "
            " } else if (typeof init === 'object' && typeof Symbol !== 'undefined' && typeof init[Symbol.iterator] === 'function') { "
            "   var it=init[Symbol.iterator](), step; "
            "   while(!(step=it.next()).done){ "
            "     var p=step.value; "
            "     if (p == null || typeof p[Symbol.iterator] !== 'function') "
            "       throw new TypeError('Query pair must be iterable'); "
            "     var pa=[]; var pit=p[Symbol.iterator](); "
            "     for (var ps;!(ps=pit.next()).done;) pa.push(ps.value); "
            "     if (pa.length !== 2) throw new TypeError('Each query pair must be an iterable [name, value] tuple'); "
            "     add(pa[0],pa[1]); "
            "   } "
            " } else if (typeof init === 'object') { "
            "   var ks=Object.keys(init); "
            "   var rec=new Map(); "
            "   for (var oi=0;oi<ks.length;oi++) rec.set(usv(ks[oi]),usv(init[ks[oi]])); "
            "   rec.forEach(function(v,k){pairs.push([k,v]);}); "
            " } else { "
            "   parse(String(init)); "
            " } "
            " var o = Object.create(proto && (proto === USPp || USPp.isPrototypeOf(proto)) ? proto : USPp); "
            " o.__ndPairs = pairs; "
            " o.__ndOwner = null; "
            " return o; "
            "}) ";
        JSValue h = JS_Eval(ctx, helper_src, strlen(helper_src),
                            "<usp-helper>", JS_EVAL_TYPE_GLOBAL | JS_EVAL_FLAG_HIDE_SOURCE);
        if (!JS_IsException(h)) {
            *usp_helper = h;
            *usp_helper_set = 1;
        } else {
            JS_FreeValue(ctx, JS_GetException(ctx));
            JS_FreeValue(ctx, h);
        }
    }
    if (!usp_helper || !*usp_helper_set) return JS_NewObject(ctx);
    JSValueConst args[2] = { init, proto };
    return JS_Call(ctx, *usp_helper, JS_UNDEFINED, 2, args);
}

static JSValue
ns_url_get_searchParams_object(JSContext *ctx, const char *search)
{
    JSValue arg = JS_NewString(ctx, search ? search : "");
    JSValue obj = ns_url_get_searchParams_value(ctx, arg, JS_UNDEFINED);
    JS_FreeValue(ctx, arg);
    if (JS_IsException(obj)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        return JS_NewObject(ctx);
    }
    return obj;
}

static JSValue
ns_window_document_fragment_ctor(JSContext *ctx, JSValueConst this_val,
                                 int argc, JSValueConst *argv)
{
    (void)this_val; (void)argc; (void)argv;
    if (!js_from_ctx(ctx)) return JS_NULL;
    ns_node *frag = ns_node_new_document();
    frag->flags |= NS_NODE_FRAGMENT;
    g_hash_table_add(js_from_ctx(ctx)->orphan_nodes, frag);
    return ns_make_element(ctx, frag);
}

static JSValue
ns_char_data_ctor(JSContext *ctx, int argc, JSValueConst *argv,
                  ns_node *(*make)(char *data, guint32 len))
{
    ns_js *js = js_from_ctx(ctx);
    if (!js) return JS_NULL;
    char *dup;
    size_t len = 0;
    if (argc >= 1 && !JS_IsUndefined(argv[0])) {
        const char *s = JS_ToCStringLen(ctx, &len, argv[0]);
        if (!s) return JS_EXCEPTION;
        dup = g_memdup2(s, len + 1);
        dup[len] = '\0';
        JS_FreeCString(ctx, s);
    } else {
        dup = g_strdup("");
    }
    ns_node *n = make(dup, (guint32)len);
    g_hash_table_add(js->orphan_nodes, n);
    JSValue wrapper = ns_make_element(ctx, n);
    ns_tag_caller_document(ctx, wrapper);
    return wrapper;
}

static JSValue
ns_window_text_ctor(JSContext *ctx, JSValueConst this_val,
                    int argc, JSValueConst *argv)
{
    (void)this_val;
    return ns_char_data_ctor(ctx, argc, argv, ns_node_new_text_len);
}

static JSValue
ns_window_comment_ctor(JSContext *ctx, JSValueConst this_val,
                       int argc, JSValueConst *argv)
{
    (void)this_val;
    return ns_char_data_ctor(ctx, argc, argv, ns_node_new_comment_len);
}

static JSValue
ns_window_image_ctor(JSContext *ctx, JSValueConst this_val,
                     int argc, JSValueConst *argv)
{
    (void)this_val;
    if (!js_from_ctx(ctx)) return JS_NULL;
    ns_node *el = ns_node_new_element(g_strdup("img"));
    if (argc >= 1) {
        int32_t w = 0;
        if (JS_ToInt32(ctx, &w, argv[0]) == 0 && w > 0) {
            char buf[16];
            g_snprintf(buf, sizeof buf, "%d", w);
            ns_element_set_attr(el, "width", buf);
        }
    }
    if (argc >= 2) {
        int32_t h = 0;
        if (JS_ToInt32(ctx, &h, argv[1]) == 0 && h > 0) {
            char buf[16];
            g_snprintf(buf, sizeof buf, "%d", h);
            ns_element_set_attr(el, "height", buf);
        }
    }
    g_hash_table_add(js_from_ctx(ctx)->orphan_nodes, el);
    return ns_make_element(ctx, el);
}

static JSValue
ns_window_audio_ctor(JSContext *ctx, JSValueConst this_val,
                     int argc, JSValueConst *argv)
{
    (void)this_val;
    if (!js_from_ctx(ctx)) return JS_NULL;
    ns_node *el = ns_node_new_element(g_strdup("audio"));
    if (argc >= 1) {
        const char *s = JS_ToCString(ctx, argv[0]);
        if (s) { ns_element_set_attr(el, "src", s); JS_FreeCString(ctx, s); }
    }
    g_hash_table_add(js_from_ctx(ctx)->orphan_nodes, el);
    return ns_make_element(ctx, el);
}

static JSValue
ns_window_option_ctor(JSContext *ctx, JSValueConst this_val,
                      int argc, JSValueConst *argv)
{
    (void)this_val;
    if (!js_from_ctx(ctx)) return JS_NULL;
    ns_node *el = ns_node_new_element(g_strdup("option"));
    if (argc >= 1) {
        const char *t = JS_ToCString(ctx, argv[0]);
        if (t) {
            ns_node_append_child(el, ns_node_new_text(g_strdup(t)));
            JS_FreeCString(ctx, t);
        }
    }
    if (argc >= 2) {
        const char *v = JS_ToCString(ctx, argv[1]);
        if (v) { ns_element_set_attr(el, "value", v); JS_FreeCString(ctx, v); }
    }
    if (argc >= 3 && JS_ToBool(ctx, argv[2]))
        ns_element_set_attr(el, "defaultSelected", "");
    if (argc >= 4 && JS_ToBool(ctx, argv[3]))
        ns_element_set_attr(el, "selected", "");
    g_hash_table_add(js_from_ctx(ctx)->orphan_nodes, el);
    return ns_make_element(ctx, el);
}

static JSValue
ns_window_usp_ctor(JSContext *ctx, JSValueConst this_val,
                   int argc, JSValueConst *argv)
{
    if (!JS_IsObject(this_val))
        return JS_ThrowTypeError(ctx, "Failed to construct 'URLSearchParams': "
            "Please use the 'new' operator, this DOM object constructor "
            "cannot be called as a function.");
    JSValue proto = JS_GetPropertyStr(ctx, this_val, "prototype");
    JSValue obj = ns_url_get_searchParams_value(ctx,
        argc >= 1 ? argv[0] : JS_UNDEFINED, proto);
    JS_FreeValue(ctx, proto);
    return obj;
}

