    if (argc >= 2 && JS_IsObject(argv[1])) {
        detail = JS_GetPropertyStr(ctx, argv[1], "detail");
        if (JS_IsUndefined(detail)) { JS_FreeValue(ctx, detail); detail = JS_NULL; }
    }
    JS_SetPropertyStr(ctx, ev, "detail", detail);
