static JSValue
ns_options_item(JSContext *ctx, JSValueConst this_val,
                int argc, JSValueConst *argv)
{
    if (argc < 1) return JS_NULL;
    int32_t idx = 0;
    JS_ToInt32(ctx, &idx, argv[0]);
    if (idx < 0) return JS_NULL;
    const ns_node *el = ns_unwrap_element(this_val);
    if (!el) return JS_NULL;
    int32_t i = 0;
    for (ns_node *c = el->first_child; c; c = c->next_sibling) {
        if (c->kind != NS_NODE_ELEMENT || !c->name) continue;
        if (g_ascii_strcasecmp(c->name, "option") == 0) {
            if (i == idx) return ns_make_element(ctx, c);
            i++;
        } else if (g_ascii_strcasecmp(c->name, "optgroup") == 0) {
            for (ns_node *cc = c->first_child; cc; cc = cc->next_sibling) {
                if (cc->kind == NS_NODE_ELEMENT && cc->name &&
                    g_ascii_strcasecmp(cc->name, "option") == 0) {
                    if (i == idx) return ns_make_element(ctx, cc);
                    i++;
                }
            }
        }
    }
    return JS_NULL;
}

static JSValue
ns_options_namedItem(JSContext *ctx, JSValueConst this_val,
                     int argc, JSValueConst *argv)
{
    if (argc < 1 || !JS_IsString(argv[0])) return JS_NULL;
    const char *name = JS_ToCString(ctx, argv[0]);
    if (!name) return JS_NULL;
    const ns_node *el = ns_unwrap_element(this_val);
    JSValue result = JS_NULL;
    if (!el) { JS_FreeCString(ctx, name); return JS_NULL; }
    GQueue q = G_QUEUE_INIT;
    g_queue_push_tail(&q, (ns_node *)el);
    while (!g_queue_is_empty(&q)) {
        ns_node *n = g_queue_pop_head(&q);
        for (ns_node *c = n->first_child; c; c = c->next_sibling) {
            if (c->kind != NS_NODE_ELEMENT || !c->name) continue;
            if (g_ascii_strcasecmp(c->name, "option") == 0) {
                const char *id = ns_element_id_attr(c);
                const char *nm = ns_element_get_attr(c, "name");
                if ((id && strcmp(id, name) == 0) ||
                    (nm && strcmp(nm, name) == 0)) {
                    result = ns_make_element(ctx, c);
                    goto done;
                }
            } else {
                g_queue_push_tail(&q, c);
            }
        }
    }
done:
    g_queue_clear(&q);
    JS_FreeCString(ctx, name);
    return result;
}

static JSValue
ns_table_insertRow(JSContext *ctx, JSValueConst this_val,
                   int argc, JSValueConst *argv)
{
    int32_t idx = -1;
    if (argc >= 1 && JS_ToInt32(ctx, &idx, argv[0])) return JS_EXCEPTION;
    ns_node *tbl = ns_unwrap_element_mut(this_val);
    if (!tbl) return JS_NULL;
    GPtrArray *rows = g_ptr_array_new();
    ns_collect_descendants_named(tbl, "tr", rows);
    if (idx > (int32_t)rows->len) idx = (int32_t)rows->len;
    ns_node *new_tr = ns_node_new_element(g_strdup("tr"));
    ns_js *_j = js_from_ctx(ctx);
    if (idx < 0 || idx == (int32_t)rows->len) {
        ns_node *parent;
        if (rows->len > 0) {
            parent = ((ns_node *)g_ptr_array_index(rows, rows->len - 1))->parent;
        } else if (ns_node_is_element_named(tbl, "table")) {
            parent = NULL;
            for (ns_node *c = tbl->first_child; c; c = c->next_sibling)
                if (ns_node_is_element_named(c, "tbody")) parent = c;
            if (!parent) {
                parent = ns_node_new_element(g_strdup("tbody"));
                ns_node_append_child(tbl, parent);
            }
        } else {
            parent = tbl;
        }
        if (!parent) parent = tbl;
        ns_node_append_child(parent, new_tr);
    } else {
        ns_node *ref = g_ptr_array_index(rows, idx);
        if (ref && ref->parent)
            ns_element_insert_before_single(_j, ref->parent, new_tr, ref);
        else
            ns_node_append_child(tbl, new_tr);
    }
    g_ptr_array_free(rows, TRUE);
    if (_j) {
        ns_js_record_child_change(_j, new_tr->parent, new_tr, NULL,
                                  new_tr->prev_sibling, new_tr->next_sibling);
        _j->mutated = TRUE;
    }
    return ns_make_element(ctx, new_tr);
}

static JSValue
ns_table_deleteRow(JSContext *ctx, JSValueConst this_val,
                   int argc, JSValueConst *argv)
{
    ns_node *tbl = ns_unwrap_element_mut(this_val);
    if (!tbl || argc < 1) return JS_UNDEFINED;
    int32_t idx = -1;
    JS_ToInt32(ctx, &idx, argv[0]);
    GPtrArray *rows = g_ptr_array_new();
    ns_collect_descendants_named(tbl, "tr", rows);
    if (idx < 0) idx = (int32_t)rows->len - 1;
    if (idx >= 0 && (uint32_t)idx < rows->len) {
        ns_node *r = g_ptr_array_index(rows, idx);
        ns_js *_j = js_from_ctx(ctx);
        ns_node *parent = r->parent;
        ns_node *prev = r->prev_sibling, *next = r->next_sibling;
        ns_node_remove(r);
        ns_js_orphan_node(_j, r);
        if (_j) {
            ns_js_record_child_change(_j, parent, NULL, r, prev, next);
            _j->mutated = TRUE;
        }
    }
    g_ptr_array_free(rows, TRUE);
    return JS_UNDEFINED;
}

static JSValue
ns_tr_insertCell(JSContext *ctx, JSValueConst this_val,
                 int argc, JSValueConst *argv)
{
    int32_t idx = -1;
    if (argc >= 1 && JS_ToInt32(ctx, &idx, argv[0])) return JS_EXCEPTION;
    ns_node *tr = ns_unwrap_element_mut(this_val);
    if (!tr) return JS_NULL;
    GPtrArray *cells = g_ptr_array_new();
    for (ns_node *c = tr->first_child; c; c = c->next_sibling) {
        if (c->kind == NS_NODE_ELEMENT && c->name &&
            (g_ascii_strcasecmp(c->name, "td") == 0 ||
             g_ascii_strcasecmp(c->name, "th") == 0))
            g_ptr_array_add(cells, c);
    }
    if (idx > (int32_t)cells->len) idx = (int32_t)cells->len;
    ns_node *cell = ns_node_new_element(g_strdup("td"));
    ns_js *_j = js_from_ctx(ctx);
    if (idx < 0 || idx == (int32_t)cells->len) {
        ns_node_append_child(tr, cell);
    } else {
        ns_node *ref = g_ptr_array_index(cells, idx);
        ns_element_insert_before_single(_j, tr, cell, ref);
    }
    g_ptr_array_free(cells, TRUE);
    if (_j) {
        ns_js_record_child_change(_j, cell->parent, cell, NULL,
                                  cell->prev_sibling, cell->next_sibling);
        _j->mutated = TRUE;
    }
    return ns_make_element(ctx, cell);
}

static JSValue
ns_tr_deleteCell(JSContext *ctx, JSValueConst this_val,
                 int argc, JSValueConst *argv)
{
    ns_node *tr = ns_unwrap_element_mut(this_val);
    if (!tr || argc < 1) return JS_UNDEFINED;
    int32_t idx = -1;
    JS_ToInt32(ctx, &idx, argv[0]);
    GPtrArray *cells = g_ptr_array_new();
    for (ns_node *c = tr->first_child; c; c = c->next_sibling) {
        if (c->kind == NS_NODE_ELEMENT && c->name &&
            (g_ascii_strcasecmp(c->name, "td") == 0 ||
             g_ascii_strcasecmp(c->name, "th") == 0))
            g_ptr_array_add(cells, c);
    }
    if (idx < 0) idx = (int32_t)cells->len - 1;
    if (idx >= 0 && (uint32_t)idx < cells->len) {
        ns_node *r = g_ptr_array_index(cells, idx);
        ns_js *_j = js_from_ctx(ctx);
        ns_node *parent = r->parent;
        ns_node *prev = r->prev_sibling, *next = r->next_sibling;
        ns_node_remove(r);
        ns_js_orphan_node(_j, r);
        if (_j) {
            ns_js_record_child_change(_j, parent, NULL, r, prev, next);
            _j->mutated = TRUE;
        }
    }
    g_ptr_array_free(cells, TRUE);
    return JS_UNDEFINED;
}

static JSValue
ns_select_add(JSContext *ctx, JSValueConst this_val,
              int argc, JSValueConst *argv)
{
    if (argc < 1) return JS_UNDEFINED;
    ns_node *sel = ns_unwrap_element_mut(this_val);
    if (!sel) return JS_UNDEFINED;
    ns_node *opt = ns_unwrap_element_mut(argv[0]);
    if (!opt || !(ns_node_is_element_named(opt, "option") ||
                  ns_node_is_element_named(opt, "optgroup")))
        return JS_ThrowTypeError(ctx, "add: argument 1 is not an option or optgroup element");
    for (const ns_node *a = sel; a; a = a->parent)
        if (a == opt)
            return ns_throw_dom_exception(ctx, "HierarchyRequestError", 3,
                                          "The element is an ancestor of the select");
    ns_js *_j = js_from_ctx(ctx);
    ns_node *before = NULL;
    if (argc >= 2 && !JS_IsNull(argv[1]) && !JS_IsUndefined(argv[1])) {
        if (JS_IsNumber(argv[1])) {
            int32_t idx = 0;
            JS_ToInt32(ctx, &idx, argv[1]);
            int32_t i = 0;
            for (ns_node *c = sel->first_child; c && !before; c = c->next_sibling) {
                if (ns_node_is_element_named(c, "option")) {
                    if (i++ == idx) before = c;
                } else if (ns_node_is_element_named(c, "optgroup")) {
                    for (ns_node *g = c->first_child; g; g = g->next_sibling)
                        if (ns_node_is_element_named(g, "option") && i++ == idx) {
                            before = g;
                            break;
                        }
                }
            }
        } else {
            before = ns_unwrap_element_mut(argv[1]);
            gboolean inside = FALSE;
            for (const ns_node *a = before ? before->parent : NULL; a; a = a->parent)
                if (a == sel) inside = TRUE;
            if (!inside)
                return ns_throw_dom_exception(ctx, "NotFoundError", 8,
                                              "The reference element is not in the select");
        }
    }
    if (before == opt) return JS_UNDEFINED;
    ns_node *parent = before ? before->parent : sel;
    if (opt->parent) ns_node_remove(opt);
    if (before) {
        ns_element_insert_before_single(_j, parent, opt, before);
    } else {
        if (_j) g_hash_table_remove(_j->orphan_nodes, opt);
        ns_node_append_child(sel, opt);
    }
    if (_j) _j->mutated = TRUE;
    return JS_UNDEFINED;
}

static JSValue
ns_element_setCustomValidity(JSContext *ctx, JSValueConst this_val,
                             int argc, JSValueConst *argv)
{
    ns_node *el = ns_unwrap_element_mut(this_val);
    if (!el) return JS_UNDEFINED;
    const char *msg = argc >= 1 ? JS_ToCString(ctx, argv[0]) : NULL;
    if (msg && *msg) ns_element_set_attr(el, NS_CUSTOM_VALIDITY_ATTR, msg);
    else            ns_element_remove_attr(el, NS_CUSTOM_VALIDITY_ATTR);
    ns_js *_j = js_from_ctx(ctx);
    if (_j) _j->mutated = TRUE;
    if (msg) JS_FreeCString(ctx, msg);
    return JS_UNDEFINED;
}

static JSValue
ns_media_canPlayType(JSContext *ctx, JSValueConst this_val,
                     int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 1 || !JS_IsString(argv[0])) return JS_NewString(ctx, "");
    const char *raw = JS_ToCString(ctx, argv[0]);
    if (!raw) return JS_NewString(ctx, "");
    const char *out = ns_media_type_support(raw);
    JS_FreeCString(ctx, raw);
    return JS_NewString(ctx, out);
}

static JSValue
ns_media_source_is_type_supported(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv)
{
    (void)this_val;
    if (argc < 1) return JS_FALSE;
    const char *raw = JS_ToCString(ctx, argv[0]);
    if (!raw) return JS_FALSE;
    char *lowered = g_ascii_strdown(raw, -1);
    const char *params = NULL;
    char *container = ns_media_type_container(lowered, &params);
    gboolean segmented = strcmp(container, "video/webm") == 0 ||
                         strcmp(container, "audio/webm") == 0 ||
                         strcmp(container, "video/mp4")  == 0 ||
                         strcmp(container, "audio/mp4")  == 0 ||
                         strcmp(container, "video/mp2t") == 0 ||
                         strcmp(container, "audio/mpeg") == 0 ||
                         strcmp(container, "audio/aac")  == 0;
    gboolean ok = segmented && *ns_media_type_support(raw) != '\0';
    g_free(container);
    g_free(lowered);
    JS_FreeCString(ctx, raw);
    return JS_NewBool(ctx, ok);
}

static JSValue
ns_media_get_paused(JSContext *ctx, JSValueConst this_val)
{
    JSValue playing_v = JS_GetPropertyStr(ctx, this_val, "_nd_playing");
    gboolean playing = JS_ToBool(ctx, playing_v);
    JS_FreeValue(ctx, playing_v);
    return JS_NewBool(ctx, !playing);
}

