static void
ns_js_reset_runtime_state(ns_js *js)
{
    if (!js) return;
    ns_popover_state_clear(js);
    js->focused_node = NULL;
    ns_js_forget_pending_change(js);
    js->focused_doc = NULL;
    js->pending_fullscreen_event_target = NULL;
    ns_storage_free_deferred_events(js);

    if (js->pending_scrollend) {
        g_ptr_array_free(js->pending_scrollend, TRUE);
        js->pending_scrollend = NULL;
    }
    js->pending_scrollend_doc = FALSE;

    if (js->timers)
        g_hash_table_remove_all(js->timers);

    if (js->media_query_lists) {
        for (guint i = 0; i < js->media_query_lists->len; i++) {
            JSValue *slot = g_ptr_array_index(js->media_query_lists, i);
            JS_FreeValue(js->ctx, *slot);
            g_free(slot);
        }
        g_ptr_array_set_size(js->media_query_lists, 0);
    }

    if (js->raf_pending) {
        for (guint i = 0; i < js->raf_pending->len; i++) {
            ns_raf_entry *e = &g_array_index(js->raf_pending, ns_raf_entry, i);
            JS_FreeValue(e->ctx ? e->ctx : js->ctx, e->cb);
        }
        g_array_set_size(js->raf_pending, 0);
    }

    if (js->listeners) {
        for (guint i = 0; i < js->listeners->len; i++) {
            ns_listener *l = g_ptr_array_index(js->listeners, i);
            JS_FreeValue(js->ctx, l->cb);
            if (JS_IsObject(l->signal)) JS_FreeValue(js->ctx, l->signal);
            g_free(l->type);
            g_free(l);
        }
        g_ptr_array_set_size(js->listeners, 0);
        ns_listener_index_clear(js);
    }

    if (js->pending_fetches) {
        for (guint i = 0; i < js->pending_fetches->len; i++) {
            ns_js_fetch_state *st = g_ptr_array_index(js->pending_fetches, i);
            JS_FreeValue(js->ctx, st->resolve);
            JS_FreeValue(js->ctx, st->reject);
            st->resolve = JS_UNDEFINED;
            st->reject  = JS_UNDEFINED;
            st->ctx = NULL;
            st->js  = NULL;
        }
        g_ptr_array_set_size(js->pending_fetches, 0);
    }

    if (js->pending_xhrs) {
        for (guint i = 0; i < js->pending_xhrs->len; i++) {
            ns_xhr_state *st = g_ptr_array_index(js->pending_xhrs, i);
            JS_FreeValue(js->ctx, st->obj);
            st->obj = JS_UNDEFINED;
            st->ctx = NULL;
            st->js  = NULL;
        }
        g_ptr_array_set_size(js->pending_xhrs, 0);
    }
    ns_js_link_fetches_detach(js);

    if (js->ce_registry) g_hash_table_remove_all(js->ce_registry);
    ns_css_clear_defined_elements();
    ns_css_clear_registered_properties();
    if (js->ce_pending)  g_hash_table_remove_all(js->ce_pending);
    if (js->ce_under_construction)
        g_hash_table_remove_all(js->ce_under_construction);
    js->ce_in_attr_callback = 0;

    if (js->async_script_source) {
        g_source_remove(js->async_script_source);
        js->async_script_source = 0;
    }
    if (js->async_script_roots)
        g_ptr_array_set_size(js->async_script_roots, 0);

    ns_attr_detach_all(js);
    ns_attribute_maps_release_all(js);
    if (js->pinned_wrappers_set)
        ns_pinned_wrappers_release(js);

    if (js->mutation_observers) {
        for (guint i = 0; i < js->mutation_observers->len; i++) {
            ns_mut_observer *o = g_ptr_array_index(js->mutation_observers, i);
            if (o) ns_mut_observer_release(js->ctx, o);
        }
    }

    if (js->intersection_observers) {
        for (guint i = 0; i < js->intersection_observers->len; i++) {
            ns_io_observer *o = g_ptr_array_index(js->intersection_observers, i);
            if (!o) continue;
            o->disconnected = TRUE;
            ns_io_observer_targets_clear(js->ctx, o);
        }
    }

    if (js->perf_observers) {
        for (guint i = 0; i < js->perf_observers->len; i++) {
            ns_perf_observer *o = g_ptr_array_index(js->perf_observers, i);
            if (o) ns_perf_observer_release(js->ctx, o);
        }
    }
    js->perf_drain_scheduled = FALSE;

    if (js->orphan_nodes) {
        GList *list = g_hash_table_get_keys(js->orphan_nodes);
        g_hash_table_remove_all(js->orphan_nodes);
        for (GList *l = list; l; l = l->next)
            ns_node_free(l->data);
        g_list_free(list);
    }

    if (js->frame_windows) {
        GHashTableIter it;
        gpointer k, val;
        g_hash_table_iter_init(&it, js->frame_windows);
        while (g_hash_table_iter_next(&it, &k, &val))
            JS_FreeValue(js->ctx, JS_MKPTR(JS_TAG_OBJECT, val));
        g_hash_table_remove_all(js->frame_windows);
    }
    ns_window_links_clear(js, FALSE);
    ns_js_drop_message_tasks(js);
    ns_realm_cloners_clear(js, FALSE);
    ns_js_clear_frame_clocks(js, FALSE);
    if (js->frame_contexts)
        g_hash_table_remove_all(js->frame_contexts);
    if (js->frame_csps)
        g_hash_table_remove_all(js->frame_csps);
    if (js->frame_urls)
        g_hash_table_remove_all(js->frame_urls);
    if (js->frame_referrers)
        g_hash_table_remove_all(js->frame_referrers);
    ns_js_drop_pending_rejections(js);
    ns_js_drop_realm_helpers(js);
    if (js->frame_ctxs) {
        for (guint i = 0; i < js->frame_ctxs->len; i++)
            JS_FreeContext(g_ptr_array_index(js->frame_ctxs, i));
        g_ptr_array_set_size(js->frame_ctxs, 0);
    }

    ns_drain_microtasks(js);
    JS_RunGC(js->rt);
}

static gboolean
ns_cookie_jar_has_name(const char *jar, const char *name, gsize name_len)
{
    if (!jar || !name || name_len == 0) return FALSE;
    const char *scan = jar;
    while ((scan = strstr(scan, name)) != NULL) {
        gboolean at_start = (scan == jar) ||
                            (*(scan - 1) == ' ' || *(scan - 1) == ';');
        if (at_start && scan[name_len] == '=') return TRUE;
        scan += name_len;
    }
    return FALSE;
}

static void
ns_js_seed_cookies_from_jar(ns_js *js)
{
    if (!js || !js->current_url || !*js->current_url) return;
    ns_net_cookie_jar_version(js->current_url, ns_js_top_url(js),
                                  &js->cookie_version);
    char *jar = ns_net_cookies_for_js(js->current_url, ns_js_top_url(js));
    if (!jar) return;
    if (!*jar) { g_free(jar); return; }

    char *existing = js->cookie_value;
    if (!existing || !*existing) {
        g_free(js->cookie_value);
        js->cookie_value = jar;
        return;
    }

    GString *merged = g_string_new(existing);
    char **pairs = g_strsplit(jar, "; ", -1);
    for (int i = 0; pairs[i]; i++) {
        const char *eq = strchr(pairs[i], '=');
        if (!eq) continue;
        gsize nlen = (gsize)(eq - pairs[i]);
        char *name = g_strndup(pairs[i], nlen);
        gboolean dup = ns_cookie_jar_has_name(merged->str, name, nlen);
        g_free(name);
        if (dup) continue;
        g_string_append(merged, "; ");
        g_string_append(merged, pairs[i]);
    }
    g_strfreev(pairs);
    g_free(jar);
    g_free(js->cookie_value);
    js->cookie_value = g_string_free(merged, FALSE);
}

static void
ns_document_lift_methods_to_proto(JSContext *ctx, JSValueConst document)
{
    JSValue proto = JS_GetPrototype(ctx, document);
    if (!JS_IsObject(proto)) { JS_FreeValue(ctx, proto); return; }
    JSPropertyEnum *tab = NULL;
    uint32_t len = 0;
    if (JS_GetOwnPropertyNames(ctx, &tab, &len, document,
            JS_GPN_STRING_MASK | JS_GPN_SYMBOL_MASK) == 0) {
        for (uint32_t i = 0; i < len; i++) {
            JSPropertyDescriptor d;
            if (JS_GetOwnProperty(ctx, &d, document, tab[i].atom) <= 0)
                continue;
            gboolean is_accessor = (d.flags & JS_PROP_GETSET) != 0;
            gboolean is_method = !is_accessor && JS_IsFunction(ctx, d.value);
            if (is_method) {
                JSPropertyDescriptor pp;
                int on_proto = JS_GetOwnProperty(ctx, &pp, proto, tab[i].atom);
                if (on_proto > 0) {
                    JS_FreeValue(ctx, pp.value);
                    JS_FreeValue(ctx, pp.getter);
                    JS_FreeValue(ctx, pp.setter);
                } else {
                    JS_DefinePropertyValue(ctx, proto, tab[i].atom,
                        JS_DupValue(ctx, d.value),
                        JS_PROP_CONFIGURABLE | JS_PROP_WRITABLE);
                }
                JS_DeleteProperty(ctx, document, tab[i].atom, 0);
            }
            JS_FreeValue(ctx, d.value);
            JS_FreeValue(ctx, d.getter);
            JS_FreeValue(ctx, d.setter);
        }
        JS_FreePropertyEnum(ctx, tab, len);
    }
    JS_FreeValue(ctx, proto);
}

static void
ns_link_class_ctor(JSContext *ctx, JSValueConst global, const char *name,
                   JSClassID class_id)
{
    JSValue ctor = JS_GetPropertyStr(ctx, global, name);
    JSValue proto = JS_GetClassProto(ctx, class_id);
    if (JS_IsObject(ctor) && JS_IsObject(proto)) {
        JS_DefinePropertyValueStr(ctx, proto, "constructor",
                                  JS_DupValue(ctx, ctor),
                                  JS_PROP_WRITABLE | JS_PROP_CONFIGURABLE);
        JS_DefinePropertyValueStr(ctx, ctor, "prototype", proto,
                                  JS_PROP_WRITABLE);
    } else {
        JS_FreeValue(ctx, proto);
    }
    JS_FreeValue(ctx, ctor);
}

